function baseBacktestView(){const a=asset(),r=E.backtest(data(),a.code,bt),hasFlow=series(a.code).some(x=>E.valid(x.netFlow));return title('笑哭脸信号与回测','skill v2.2信号公式 · 独立的时序与成交研究模型。',selectAsset('bt-select',true))+attribution(3)+notice(isDemo()?'价格与资金均为合成数据。回测验证交互和规则，不代表实盘表现；合成观察日不是真实交易日历。':mode==='local'?'使用未复权真实日线。分红除权和执行模型可能影响收益，研究回测不等于实盘表现。':'仅使用导入样本；仍需独立核实交易日历、复权、数据及产品交易规则，不作为实盘绩效证明。')+`<div class="backtest-layout"><aside class="panel form-panel"><div class="panel-head"><h2>研究参数</h2>${pill('可重算','good')}</div><div class="panel-body"><div class="field"><label for="bt-start">起始日期</label><input type="date" id="bt-start" value="${bt.start}" onchange="changeBacktestDate('start',this.value)"></div><div class="field"><label for="bt-end">结束日期</label><input type="date" id="bt-end" value="${bt.end}" onchange="changeBacktestDate('end',this.value)"></div><div class="field"><label for="bt-execution">执行研究模型</label><select id="bt-execution" onchange="bt.execution=this.value;render()"><option value="open" ${bt.execution==='open'?'selected':''}>次日开盘价格假设</option><option value="limit" ${bt.execution==='limit'?'selected':''}>信号收盘价 ± 限价</option></select></div><div class="field"><label for="bt-position">研究仓位（非实际持仓）</label><select id="bt-position" onchange="bt.position=Number(this.value);render()">${[25,50,75,100].map(v=>`<option value="${v}" ${bt.position===v?'selected':''}>${v}%</option>`).join('')}</select></div><div class="fields-two"><div class="field"><label for="bt-fee">单边成本 bp</label><input type="number" id="bt-fee" min="0" max="100" value="${bt.fee}" onchange="bt.fee=Math.max(0,Math.min(100,Number(this.value)||0));render()"></div><div class="field"><label for="bt-slip">滑点 bp</label><input type="number" id="bt-slip" min="0" max="100" value="${bt.slip}" onchange="bt.slip=Math.max(0,Math.min(100,Number(this.value)||0));render()"></div></div>${bt.execution==='limit'?`<div class="field"><label for="bt-limit">信号价买折 / 卖溢（%）</label><input type="number" id="bt-limit" min="0" max="15" value="${bt.limit}" onchange="bt.limit=Math.max(0,Math.min(15,Number(this.value)||0));render()"></div>`:''}<label class="check-row"><input type="checkbox" ${bt.enhanced?'checked':''} onchange="bt.enhanced=this.checked;render()">三因子增强${hasFlow?'':'（资金缺失则不启用资金增强）'}</label><label class="check-row"><input type="checkbox" ${bt.marketGate?'checked':''} onchange="bt.marketGate=this.checked;render()">六ETF走弱过滤（研究参数4/6）</label><button class="btn primary" onclick="chartMemory=null;render();toast('K线、信号与回测已同步重算')">${icon('refresh')}重新计算</button><div class="small muted" style="margin-top:12px">初始研究资金¥100,000；研究单位100。尚未覆盖全部产品交易规则。市场过滤按历史信号日判断。</div></div></aside><div>${r.error?panel('没有可计算样本',`<div class="empty">${r.error}。请修改区间或导入数据。</div>`):`<div class="submetrics"><div class="submetric"><label>研究策略收益</label><strong class="num ${cls(r.ret)}">${change(r.ret)}</strong><small>${mode==='local'?'真实日线':isDemo()?'合成':'导入'}数据 · 含设定成本</small></div><div class="submetric"><label>样本内最大回撤</label><strong class="num">−${num(r.dd)}%</strong><small>每日收盘估值</small></div><div class="submetric"><label>完成交易 / 胜率</label><strong class="num">${r.completed} / ${r.win===null?'—':num(r.win,0)+'%'}</strong><small>只统计已平仓</small></div><div class="submetric"><label>模拟成交 / 订单</label><strong class="num">${r.trades.length} / ${r.orders.length}</strong><small>保留未成交原因</small></div></div>${panel(a.name+' · K线与信号',`<div class="legend"><span><i style="background:#c5a262"></i>SHORTL</span><span><i style="background:#6b8db9"></i>MIDL</span><span><i style="background:#997ba9"></i>MA60</span><span><i style="background:#9aafb6"></i>布林上下轨</span><span>买N=3/3 · 卖N=5/5</span></div><div class="chart-wrap">${candleChart(r)}</div><div class="panel-note">图中保留盘中K线及暂定信号；成交与绩效仅使用已确认收盘K线。改变日期或重算后同步更新。</div>`,pill(mode==='local'?'真实收盘样本':isDemo()?'合成样本':'导入样本','warn'),'panel-space')}<section class="panel"><div class="tabs">${[['equity','净值与基准'],['orders','订单与未成交'],['signals','研究信号'],['method','方法与限制']].map(([id,t])=>`<button class="tab ${state.btTab===id?'active':''}" onclick="state.btTab='${id}';render()">${t}</button>`).join('')}</div>${btResult(r)}</section>`}</div></div>`}
function btResult(r){if(state.btTab==='equity')return `<div class="legend"><span><i></i>研究策略</span><span><i class="dashed"></i>同区间买入持有（不扣成本）</span></div><div class="chart-wrap">${lineChart(r.net,{height:220,unit:'%',second:r.hold,labels:[r.bars[0].date,r.bars.at(-1).date]})}</div><div class="panel-note">期末模拟资产${money(r.lastEquity)}，现金${money(r.cash)}，剩余模拟单位${r.units}。基准不扣成本、策略含成本，不等同严格可比的超额收益归因。</div>`;if(state.btTab==='orders')return btOrdersTable(r);if(state.btTab==='signals')return `<div class="table-wrap"><table><thead><tr><th>形成时间</th><th>信号</th><th>POS / 量比</th><th>三因子分</th><th>触发依据</th></tr></thead><tbody>${r.signals.map(s=>`<tr><td>${s.date} 收盘</td><td>${face(s)}</td><td class="num">${num(s.pos)} / ${num(s.vr)}</td><td class="num">${num(s.score)}${s.score===null?'（资金缺失）':''}</td><td>${s.reason}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">无信号或预热样本不足60条。</td></tr>'}</tbody></table></div>`;return `<div class="panel-body">${[['信号来源','三重EMA、SHORTL/MIDL、N3/3买入与N5/5卖出，参考skill v2.2'],['盘中快照','图表与监控包含盘中K线；暂定笑哭脸单独标记。历史回测和成交仅用completed=true的K线。'],['仓位简化','A/B使用同一研究仓位，C跳过；普通及强哭脸统一平仓，暂未实现分级减仓。'],['资金缺失','保持null，资金增强及完整三因子分不启用，不填0'],['时序修正','收盘后产生订单，不采用“未成交再回到同日开盘价”'],['限价模型','按信号收盘价定价；次日严格穿价仅为研究成交假设，不保证排队成交'],['市场过滤','六ETF历史信号日MA10；缺历史时跳过新增模拟，不回填今天状态'],['未覆盖约束','真实涨跌停、竞价、排队、部分成交、税费明细和完整交易单位'],['公司行动','统一声明复权口径；尚未完整处理现金分红和公司行动'],['取数服务',mode==='local'?'本地服务每次刷新最近640条日线并校验，未确认收盘K线剔除；财务披露与历史资金流按各自来源日期更新。':'当前手动导入全量快照；未接入skill v2.2自动增量取数服务']].map(([a,b])=>`<div class="method-row"><strong>${a}</strong><p>${b}</p></div>`).join('')}</div>`}
function getNotes(){try{const a=JSON.parse(localStorage.getItem('risklens-v2-notes')||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function noteDialog(topic='七维研究'){modal('记录研究判断',`<form id="note-form"><div class="field"><label>研究标的</label><input value="${esc(asset().name)} · ${asset().code}" readonly></div><div class="field"><label for="note-kind">问题性质</label><select id="note-kind"><option>不确定</option><option>暂时性假设</option><option>结构性假设</option></select></div><div class="field"><label for="note-evidence">事实证据与来源</label><textarea id="note-evidence" required maxlength="800" placeholder="记录事实、出处和数据时间。"></textarea></div><div class="field"><label for="note-counter">反证与后续验证条件</label><textarea id="note-counter" required maxlength="800" placeholder="什么证据会推翻判断？什么时候复核？"></textarea></div><button class="btn primary" type="submit">保存到当前浏览器</button></form>`);$('#note-form').onsubmit=e=>{e.preventDefault();const notes=getNotes();notes.unshift({code:state.code,name:asset().name,topic,kind:$('#note-kind').value,evidence:$('#note-evidence').value,counter:$('#note-counter').value,time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),environment:isDemo()?'合成演示':'导入快照'});try{localStorage.setItem('risklens-v2-notes',JSON.stringify(notes));$('#dialog').close();toast('研究记录已保存在当前浏览器')}catch{toast('当前浏览器无法保存记录')}}}
function review(){const notes=getNotes();return title('研究复盘','保留判断的来由、反证和当时的数据环境。',selectAsset()+button('新增研究记录',"noteDialog()",true,'plus'))+`<div class="grid-three">${[['事实','记录财报、价格、事件原文与披露时间，不以最新数据冒充历史已知。'],['解释','区分情绪修复、经营改善和估值重估，保留不确定项。'],['验证','记录失效条件、样本外表现和未成交原因。']].map(([t,s])=>panel(t,`<div class="panel-body"><p class="muted small">${s}</p></div>`)).join('')}</div>${panel('研究记录',notes.length?`<div class="panel-body timeline">${notes.map(n=>`<article class="timeline-item"><div class="timeline-date">${esc(n.time)}<br>${esc(n.environment)}</div><div><h3>${esc(n.name)} · ${esc(n.topic)} ${pill(esc(n.kind),'warn')}</h3><p><strong>事实与来源：</strong>${esc(n.evidence)}</p><p><strong>反证与验证：</strong>${esc(n.counter)}</p><button class="text-button" onclick="setAsset('${esc(n.code)}','research')">回到个股研究</button></div></article>`).join('')}</div>`:'<div class="empty">尚无研究记录。从七维分析、情绪偏离或本页新增一条判断。</div>',pill('本地保存'))}`}
function dataCenter(){const schema={instruments:{'002281':{source:'你的数据来源',as_of:'YYYY-MM-DD',adjustment:'qfq',completed:true,bars:[{date:'YYYY-MM-DD',open:10,high:11,low:9,close:10.5,vol:1000}],fundamentals:{pe:null}}}};return title('数据与方法','明确哪些是事实、哪些是计算、哪些仍待补齐。',button(isDemo()?'切换快照模式':'返回演示模式',"switchMode()",true))+localPanel()+`<div class="grid-two">${panel('数据模式与导入',`<div class="panel-body"><div class="definition-row"><span>当前模式</span><strong>${mode==='local'?'本地真实行情':isDemo()?'合成演示':'导入快照'}</strong></div><div class="definition-row"><span>已保存导入标的</span><strong>${uploaded?Object.keys(uploaded.instruments).length:0} / ${CATALOG.length}</strong></div><p class="small muted" style="margin:15px 0">导入仅存当前浏览器；校验日期、OHLC、来源、复权口径及上市前数据，不自动认证来源真实性。</p><div class="actions"><label class="btn primary" for="snapshot-file">${icon('folder')}选择JSON快照</label><input type="file" id="snapshot-file" accept="application/json,.json" hidden onchange="importSnapshot(this.files[0])">${button('下载合成格式样例',"downloadSample()",false,'download')}</div><p class="small muted" style="margin-top:12px">格式样例明确标为合成数据，不可直接当真实快照导入。</p></div>`)}${panel('数据结构与校验',`<div class="panel-body"><pre class="code-sample">${esc(JSON.stringify(schema,null,2))}</pre><p class="small muted">日期升序无重复；缺失用null；导入成交量统一为股/份，netFlow为元。本地兜底源如保留原始单位，将单列说明且仅用于量比。财务须注明来源与报告期间。</p></div>`)}</div>${panel('标的与覆盖',`<div class="table-wrap"><table><thead><tr><th>标的</th><th>角色</th><th>来源 / 日期</th><th>样本</th><th>口径</th><th>状态</th></tr></thead><tbody>${CATALOG.map(a=>{const r=obs(a.code);return `<tr><td>${a.name} <span class="stock-code">${a.code}</span></td><td>${a.watch?'自选 ':''}${a.benchmark?'市场观察':''}</td><td style="white-space:normal;max-width:260px">${esc(r?.source||'待导入')}<div class="table-sub">${esc(r?.as_of||'—')}</div></td><td>${r?.bars?.length||0}</td><td>${r?.adjustment||'—'}</td><td>${pill(r?isDemo()?'合成样本':r.completed?'声明完整收盘':'盘中未确认':'缺失',r?'good':'warn')}</td></tr>`}).join('')}</tbody></table></div>`)}<div class="section-heading" style="margin-top:24px"><h2>四个技能的应用与适配</h2></div><div class="grid-two">${SKILL_MAP.map(s=>panel(s.name,`<div class="panel-body"><p class="small muted">${s.detail}</p><div class="definition-row"><span>对应模块</span><strong>${s.pages}</strong></div><a class="text-button" href="${s.url}" target="_blank" rel="noopener">查看已安装技能 ${icon('arrow')}</a></div>`)).join('')}</div>${panel('研究约束与本版范围',`<div class="panel-body">${[['情绪偏离','不把下跌自动解释为错杀；没有真实证据时不打偏差总分，不沿用无来源历史概率。'],['估值与基本面','不输出固定政策溢价和通用合理倍数；股份支付不重复扣减；不将40法则套用所有科技企业。'],['多因子','按技能子指标结构计算。仅自选截面，未实施行业中性；不拼接新股历史，缺失不补分。'],['笑哭脸','应用v2.2信号公式，修正回溯成交假设；资金缺失不补0；市场过滤按历史日期。'],['当前范围','暂不建设持仓、账户与损失预算。本地模式可手动刷新真实日线；无券商、自动下单或无人值守后台监控。']].map(([n,t])=>`<div class="method-row"><strong>${n}</strong><p>${t}</p></div>`).join('')}</div>`)}<div style="margin-top:18px">${notice('身份核验与财务行情分开：长鑫科技代码来自上交所上市公告；基金名称参照管理人/披露文件。身份核实不代表合成价格、财务或研判是真实市场数据。')}</div><div class="source-links"><a href="${IDENTITY_SOURCES.cxmt}" target="_blank" rel="noopener">长鑫科技上市公告</a><a href="${IDENTITY_SOURCES.a500}" target="_blank" rel="noopener">国泰ETF清单</a><a href="${IDENTITY_SOURCES.n1000}" target="_blank" rel="noopener">南方基金产品</a><a href="${IDENTITY_SOURCES.efund}" target="_blank" rel="noopener">易方达基金披露</a></div>`}
async function importSnapshot(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('文件请控制在8MB以内');const raw=JSON.parse(await file.text());if(raw.data_kind==='synthetic')throw Error('合成格式样例不能当作真实快照导入');const clean=E.validateSnapshot(raw);localStorage.setItem('risklens-v2-snapshot',JSON.stringify(clean));uploaded=clean;mode='uploaded';localStorage.setItem('risklens-v2-mode',mode);render();toast('快照已导入，请继续核实来源与完整性')}catch(e){toast('导入失败：'+e.message)}}
function downloadSample(){const sample={data_kind:'synthetic',note:'合成格式样例，不可当真实行情',instruments:{'002281':{source:'格式示例，请替换为真实来源',as_of:'2026-10-29',adjustment:'qfq',completed:true,bars:[{date:'2026-10-28',open:10,high:11,low:9,close:10.2,vol:1000,netFlow:null},{date:'2026-10-29',open:10.2,high:11,low:10,close:10.5,vol:1200,netFlow:null}],fundamentals:{source:'财报/估值来源',period:'报告期间',pe:null,pb:null,ps:null}}}};const url=URL.createObjectURL(new Blob([JSON.stringify(sample,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='RiskLens_Synthetic_Schema_Example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function backtest(){const view=baseBacktestView(),r=E.backtest(data(),state.code,bt);return r.error?view+panel(asset().name+" · 当前日期K线",`<div class="chart-wrap">${candleChart()}</div>`):view}

function btOrdersTable(r){
 const hasTrades=r.fillCount>0,total=hasTrades?r.ret:null;
 const rows=r.orders.map(o=>`<tr><td>${esc(o.signal)} → ${esc(o.date)}</td><td>${o.type==='buy'?'买入':'卖出'}</td><td>${pill(o.status,o.price!==null?'good':'warn')}</td><td class="num">${num(o.price,3)} / ${o.qty}</td><td class="num">${E.valid(o.cycleReturn)?`<strong class="${cls(o.cycleReturn)}">${change(o.cycleReturn)}</strong><div class="table-sub">合并 ${o.cycleBuyCount} 笔买入</div>`:'<span class="muted">—</span>'}</td><td class="return-explain">${esc(o.reason)}${E.valid(o.cycleReturn)?`<div class="table-sub">对应买入成本 ${money(o.cycleBuyCost)} · 卖出净额 ${money(o.cycleNetProceeds)}</div>`:''}</td></tr>`).join('');
 return `<div class="table-wrap"><table class="bt-orders"><thead><tr><th>信号日 → 执行日</th><th>方向</th><th>状态</th><th>价格 / 数量</th><th>本轮收益率（卖出时）</th><th>说明</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty">没有可执行订单；期末信号不会越界成交。</td></tr>'}</tbody><tfoot><tr><td colspan="4"><strong>总收益率（当前区间全部成交）</strong><div class="table-sub">${hasTrades?esc(r.firstTradeDate)+' 首笔成交 → '+esc(r.bars.at(-1).date)+' 回测期末':'当前区间尚无成交'}</div></td><td class="num"><strong class="${E.valid(total)?cls(total):'muted'}">${E.valid(total)?change(total):'—'}</strong></td><td class="return-explain">${hasTrades?`初始资金 ${money(r.capital)} · 期末资产 ${money(r.lastEquity)}<div class="table-sub">已实现盈亏 ${money(r.realizedProfit)}${r.units>0?'；含剩余 '+r.units+' 单位的期末估值':'；期末空仓'}</div>`:'成交后再计算；未成交与跳过订单不参与收益统计。'}</td></tr></tfoot></table></div><div class="panel-note">本轮收益率＝（卖出净额－对应买入成本）÷对应买入成本。按实际成交买入合并计算；部分卖出按数量分摊成本。买卖费用已扣除，滑点体现在成交价格中，未成交不参与。<br>总收益率＝期末资产÷初始资金－1，含期末未平仓估值，与上方策略收益一致；仅统计当前日期区间。当前执行模型建仓后不重复加仓。</div>`
}
